:root {
  --bg: #2d2a4a;
  --card-bg: #f5f3ff;
  --text: #1e1b2e;
  --accent: #6c5ce7;
  --accent-hover: #5a4bd1;
  --accent-pressed: #4a3cb8;
  --focus: #ffd166;
  --border: #d1cde8;
  --shadow: 0 8px 24px rgba(0, 0, 0, 0.25);
  --radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at 30% 20%, #3e3a66, #1e1b2e);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 24px 16px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 32px 24px;
  width: 100%;
  max-width: 720px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  text-align: center;
  letter-spacing: -0.02em;
}

.subtitle {
  text-align: center;
  font-size: 1rem;
  color: #5a5670;
  margin-top: -12px;
}

.swatches {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 12px;
}

.swatch {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  border-radius: 10px;
  overflow: hidden;
  border: 2px solid var(--border);
  transition: border-color 0.15s ease, transform 0.15s ease;
  background: #fff;
}

.swatch.locked {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}

.swatch-color {
  height: 100px;
  width: 100%;
  transition: background-color 0.2s ease;
}

.swatch-info {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 8px 4px;
  gap: 6px;
}

.hex-code {
  font-family: 'SF Mono', 'Cascadia Code', 'Consolas', monospace;
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  user-select: all;
}

.lock-btn {
  background: none;
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 4px 8px;
  font-size: 0.75rem;
  font-weight: 600;
  cursor: pointer;
  color: #5a5670;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
  line-height: 1.2;
  display: flex;
  align-items: center;
  gap: 4px;
}

.lock-btn:hover {
  background: #ebe8f8;
  border-color: var(--accent);
  color: var(--accent);
}

.lock-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.lock-btn:active {
  transform: scale(0.95);
}

.lock-btn[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.lock-btn[aria-pressed="true"]:hover {
  background: var(--accent-hover);
}

.lock-icon {
  font-size: 0.875rem;
  line-height: 1;
}

.generate-btn {
  align-self: center;
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 14px 32px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
  box-shadow: 0 4px 12px rgba(108, 92, 231, 0.35);
  min-width: 200px;
}

.generate-btn:hover {
  background: var(--accent-hover);
  box-shadow: 0 6px 16px rgba(108, 92, 231, 0.45);
}

.generate-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.generate-btn:active {
  background: var(--accent-pressed);
  transform: scale(0.97);
  box-shadow: 0 2px 6px rgba(108, 92, 231, 0.3);
}

@media (max-width: 560px) {
  .swatches {
    grid-template-columns: repeat(2, 1fr);
  }
  .swatch:last-child {
    grid-column: span 2;
    max-width: 50%;
    justify-self: center;
  }
  .swatch-color {
    height: 80px;
  }
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
}

@media (max-width: 400px) {
  .swatches {
    grid-template-columns: 1fr;
  }
  .swatch:last-child {
    grid-column: auto;
    max-width: none;
  }
  .swatch-color {
    height: 60px;
  }
  .generate-btn {
    width: 100%;
    min-width: unset;
  }
}

(function () {
  'use strict';

  var swatchesContainer = document.getElementById('swatches');
  var generateBtn = document.getElementById('generate');

  var palette = [];
  var locked = [false, false, false, false, false];

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    var a = s * Math.min(l, 1 - l);
    var f = function (n) {
      var k = (n + h / 30) % 12;
      var color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return '#' + f(0) + f(8) + f(4);
  }

  function randomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  function generateHarmoniousPalette() {
    var baseHue = randomInt(0, 359);
    var baseSat = randomInt(55, 85);
    var baseLight = randomInt(40, 60);

    var scheme = randomInt(0, 2);
    var hues = [];

    if (scheme === 0) {
      // Analogous
      hues = [baseHue, baseHue + 30, baseHue + 60, baseHue - 30, baseHue - 60];
    } else if (scheme === 1) {
      // Complementary + split
      hues = [baseHue, baseHue + 180, baseHue + 150, baseHue + 210, baseHue + 30];
    } else {
      // Triadic
      hues = [baseHue, baseHue + 120, baseHue + 240, baseHue + 60, baseHue + 180];
    }

    return hues.map(function (h, i) {
      var hue = ((h % 360) + 360) % 360;
      var sat = Math.min(95, Math.max(35, baseSat + randomInt(-15, 15)));
      var light = Math.min(75, Math.max(30, baseLight + randomInt(-15, 15)));
      return hslToHex(hue, sat, light);
    });
  }

  function renderPalette() {
    swatchesContainer.innerHTML = '';
    palette.forEach(function (hex, index) {
      var swatch = document.createElement('div');
      swatch.className = 'swatch' + (locked[index] ? ' locked' : '');

      var colorDiv = document.createElement('div');
      colorDiv.className = 'swatch-color';
      colorDiv.style.backgroundColor = hex;

      var info = document.createElement('div');
      info.className = 'swatch-info';

      var hexSpan = document.createElement('span');
      hexSpan.className = 'hex-code';
      hexSpan.textContent = hex;

      var lockBtn = document.createElement('button');
      lockBtn.type = 'button';
      lockBtn.className = 'lock-btn';
      lockBtn.setAttribute('aria-pressed', locked[index] ? 'true' : 'false');
      lockBtn.setAttribute('aria-label', (locked[index] ? 'Unlock' : 'Lock') + ' color ' + hex);
      lockBtn.innerHTML = '<span class="lock-icon" aria-hidden="true">' + (locked[index] ? '🔒' : '🔓') + '</span> ' + (locked[index] ? 'Locked' : 'Lock');

      lockBtn.addEventListener('click', function () {
        locked[index] = !locked[index];
        renderPalette();
      });

      info.appendChild(hexSpan);
      info.appendChild(lockBtn);
      swatch.appendChild(colorDiv);
      swatch.appendChild(info);
      swatchesContainer.appendChild(swatch);
    });
  }

  function generate() {
    var newPalette = generateHarmoniousPalette();
    for (var i = 0; i < 5; i++) {
      if (!locked[i]) {
        palette[i] = newPalette[i];
      }
    }
    renderPalette();
  }

  generateBtn.addEventListener('click', generate);

  // Initial palette
  palette = generateHarmoniousPalette();
  renderPalette();
})();
